package vn.eventplatform.ad.dto;
import jakarta.validation.constraints.*; import vn.eventplatform.ad.enums.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
public final class Requests { private Requests(){} public record PackageRequest(@NotBlank String name,String description,@NotNull @DecimalMin("0") BigDecimal price,@NotNull @Min(1) Integer durationDays,Boolean active){} public record PositionPriceRequest(@NotNull BannerPosition position,@NotNull @DecimalMin("0") BigDecimal bonusPrice,Boolean active){} public record CampaignRequest(@NotNull UUID packageId,@NotBlank String name,@NotNull PricingMode pricingMode,@NotEmpty List<@NotNull BannerPosition> positions,@NotNull LocalDateTime startsAt,@NotNull LocalDateTime endsAt,@DecimalMin("0") BigDecimal escrowAmount){} public record BannerRequest(@NotNull UUID campaignId,String imageUrl,@NotNull BannerPosition position,@Min(0) Integer priority,@NotNull LocalDateTime startsAt,@NotNull LocalDateTime endsAt,Boolean active){} public record DecisionRequest(String reason){} }
